#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007;
int main() {
    int n;
    scanf("%d", &n);
    vector<int> a(n);
    for (auto &x : a) scanf("%d", &x);
    // dp[x]: number of valid prefixes whose last b value is x.
    vector<long long> dp(a[0] + 1, 1);
    for (int i = 1; i < n; i++) {
        int need = max(0, a[i] - a[i - 1]); // b must grow by at least this much
        vector<long long> pref(dp.size());
        long long running = 0;
        for (size_t j = 0; j < dp.size(); j++) { running = (running + dp[j]) % MOD; pref[j] = running; }
        vector<long long> nxt(a[i] + 1, 0);
        for (int b = 0; b <= a[i]; b++) {
            int prev = b - need;
            if (prev >= 0) nxt[b] = pref[min<size_t>(prev, dp.size() - 1)];
        }
        dp.swap(nxt);
    }
    long long total = 0;
    for (long long v : dp) total = (total + v) % MOD;
    printf("%lld\n", total);
}

import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        final long MOD = 1000000007L;
        int n = nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nextInt();
        // dp[x]: number of valid prefixes whose last b value is x.
        long[] dp = new long[a[0] + 1];
        java.util.Arrays.fill(dp, 1);
        for (int i = 1; i < n; i++) {
            int need = Math.max(0, a[i] - a[i - 1]); // b must grow by at least this much
            long[] pref = new long[dp.length];
            long running = 0;
            for (int j = 0; j < dp.length; j++) { running = (running + dp[j]) % MOD; pref[j] = running; }
            long[] nxt = new long[a[i] + 1];
            for (int b = 0; b <= a[i]; b++) {
                int prev = b - need;
                if (prev >= 0) nxt[b] = pref[Math.min(prev, dp.length - 1)];
            }
            dp = nxt;
        }
        long total = 0;
        for (long v : dp) total = (total + v) % MOD;
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

const mod = 1000000007

func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	// dp[x]: number of valid prefixes whose last b value is x.
	dp := make([]int, a[0]+1)
	for i := range dp {
		dp[i] = 1
	}
	for i := 1; i < n; i++ {
		need := max(0, a[i]-a[i-1]) // b must grow by at least this much
		pref := make([]int, len(dp))
		running := 0
		for j, x := range dp {
			running = (running + x) % mod
			pref[j] = running
		}
		nxt := make([]int, a[i]+1)
		for b := 0; b <= a[i]; b++ {
			if prev := b - need; prev >= 0 {
				nxt[b] = pref[min(prev, len(dp)-1)]
			}
		}
		dp = nxt
	}
	total := 0
	for _, v := range dp {
		total = (total + v) % mod
	}
	fmt.Println(total)
}
